class Solution:
 def countOperations(self,num1,num2):
  ans=0
  while num1 and num2:
   if num1>=num2:num1-=num2
   else:num2-=num1
   ans+=1
  return ans

class Solution:
 def countPairs(self,nums,k):
  ans=0
  for i in range(len(nums)):
   for j in range(i+1,len(nums)):
    if nums[i]==nums[j] and (i*j)%k==0:ans+=1
  return ans

class Solution:
 def countEven(self,num):
  def even(x):return sum(map(int,str(x)))%2==0
  return sum(even(x) for x in range(1,num+1))

class Solution:
 def cellsInRange(self,s):
  a,b=s.split(':');c1,r1=ord(a[0]),int(a[1:]);c2,r2=ord(b[0]),int(b[1:])
  return [chr(c)+str(r) for c in range(c1,c2+1) for r in range(r1,r2+1)]

class Solution:
 def findKDistantIndices(self,nums,key,k):
  hits=[j for j,x in enumerate(nums) if x==key]
  return [i for i in range(len(nums)) if any(abs(i-j)<=k for j in hits)]
